def shortest_path(graph, src, dst, level = {}, path = [], leveln = 0):
    # Step 1: Initialize
    level = {f"{src}": 0, f"t{dst)": 0}  # To ensure we have paths leading to the level, use a special node
    path = {f"{src}": [], f"t{dst}": []}

    # Step 2: Iterate through the graph
    while level:
        next_level = {}
        for node, dist in list(level.items()):
            if node.startswith("t"):
                return (dist, path[node])
            for n, w in graph.get(node[1:], []):
                if f"{n}" not in level:
                    next_level[f"{n}"] = dist + w
                    path[f"{n}"] = path[node] + [n]
        level = next_level
        leveln += 1
        if leveln > 100:  # To avoid infinite loops
            return (float("inf"), None)

    # Step 3: Return if not found
    return (float("inf"), None)

